class TrainingDynamicsAnalyzer:
    def __init__(self):
        self.steps = []  # list of dicts

    def record_step(self, gen_accuracy: float,
                    disc_accuracy: float) -> float:
        challenge_score = gen_accuracy * (1 - disc_accuracy)
        self.steps.append({
            "gen_accuracy": gen_accuracy,
            "disc_accuracy": disc_accuracy,
            "challenge_score": challenge_score,
        })
        return challenge_score

    def get_curriculum_phase(self, step_index: int) -> str:
        gen = self.steps[step_index]["gen_accuracy"]
        if gen < 0.3:
            return "easy"
        if gen < 0.7:
            return "medium"
        return "hard"

    def signal_advantage(self, mask_ratio: float) -> float:
        return 1.0 / mask_ratio

    @property
    def total_steps(self) -> int:
        return len(self.steps)

    @property
    def avg_challenge_score(self) -> float:
        if not self.steps:
            return 0.0
        return sum(s["challenge_score"] for s in self.steps) / len(self.steps)


# Test:
analyzer = TrainingDynamicsAnalyzer()

cs1 = analyzer.record_step(0.1, 0.9)
print(f"{cs1:.2f}")
print(analyzer.get_curriculum_phase(0))

cs2 = analyzer.record_step(0.5, 0.6)
print(f"{cs2:.2f}")
print(analyzer.get_curriculum_phase(1))

cs3 = analyzer.record_step(0.8, 0.85)
print(f"{cs3:.2f}")
print(analyzer.get_curriculum_phase(2))

print(analyzer.total_steps)
print(f"{analyzer.avg_challenge_score:.2f}")
print(f"{analyzer.signal_advantage(0.15):.1f}")
